/**
 * Fond de carte de la France métropolitaine, découpé par département.
 *
 * Généré une fois pour toutes à partir du jeu de données ouvert de l'État
 * (france-geojson, version simplifiée), reprojeté en Lambert conique conforme —
 * les paramètres officiels français, ceux qui donnent à l'hexagone sa forme
 * reconnaissable — puis simplifié par Douglas-Peucker jusqu'à une tolérance de
 * 1,5 unité de la vue.
 *
 * Figé dans le dépôt plutôt que chargé à l'exécution : les frontières
 * départementales ne bougent pas, et une carte qui dépend d'un service tiers
 * disparaît le jour où celui-ci tombe.
 *
 * Ne pas retoucher à la main. Pour changer la finesse du tracé, il faut
 * régénérer le fichier entier depuis la source.
 */

/** Repère du tracé : toutes les coordonnées ci-dessous vivent dedans. */
export const MAP_VIEWBOX = { width: 1000, height: 933 } as const;

/*
 * Constantes de la projection utilisée pour produire les tracés. Placer un
 * point sur cette carte impose de refaire exactement le même calcul : c'est
 * l'objet de `projectToMap`, dans le module de domaine.
 */
export const MAP_PROJECTION = {
  minX: -0.09362313780269853,
  maxY: 0.08010727139522333,
  scale: 5601.068121145249,
} as const;

export interface DepartmentShape {
  /** Code INSEE : « 31 », « 2A »… */
  code: string;
  name: string;
  /** Tracé SVG, déjà exprimé dans le repère de `MAP_VIEWBOX`. */
  path: string;
}

